<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class LaunchScanner implements SiteDoctorScanner{public function id():string{return 'indexability';}public function label():string{return 'Launch Readiness';}public function scan():array{$o=[];$visible=(int)get_option('blog_public',1);if(!$visible)$o[]=$this->i('search-engines-discouraged','indexability','critical','manual_only','Search engine visibility is disabled','WordPress is configured to discourage search engines from indexing this site.','Enable search engine visibility when the site is ready for public indexing.');$home=get_page_by_path('home');if(!$home&&!get_option('page_on_front'))$o[]=$this->i('no-static-home','technical','info','manual_only','No static homepage is configured','The site is not using a static page as the homepage.','Confirm that the current homepage behavior is intentional.');if(!get_option('admin_email'))$o[]=$this->i('missing-admin-email','technical','high','manual_only','Administration email is missing','WordPress does not have an administration email configured.','Set a valid administration email for site notifications.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
